import { onBeforeUnmount, onMounted } from 'vue'
import { useUiStore } from '@/stores/ui'

/** Интерфейс и курсор прячутся, если мышью/пальцем ничего не делали `timeout` мс */
export function useIdle(timeout = 2500) {
  const ui = useUiStore()
  let timer = null

  const wake = () => {
    ui.awake = true
    clearTimeout(timer)
    timer = setTimeout(() => {
      ui.awake = false
    }, timeout)
  }

  const events = ['pointermove', 'pointerdown', 'wheel', 'keydown']
  onMounted(() => {
    events.forEach((e) => window.addEventListener(e, wake, { passive: true }))
    wake()
  })
  onBeforeUnmount(() => {
    events.forEach((e) => window.removeEventListener(e, wake))
    clearTimeout(timer)
  })
}
