<template>
  <SideDrawer side="left" :open="open" @close="ui.closePanel()" @leave="onLeave">
    <template #title>
      <h2>Карты</h2>
    </template>

    <TransitionGroup tag="ul" name="list" class="maps">
      <li
        v-for="(map, index) in maps.maps"
        :key="map.id"
        class="map-item"
        :class="{ 'is-current': map.id === currentId }"
      >
        <router-link :to="`/map/${map.id}`" class="map-item__link" @click="onPick">
          <span
            class="map-item__thumb"
            :style="thumbStyle(map)"
          >
            <span v-if="!map.image">{{ map.icon }}</span>
          </span>
          <span class="map-item__text">
            <span class="map-item__name">{{ map.name }}</span>
            <span class="map-item__meta">
              <span v-if="index < 9"><kbd>{{ index + 1 }}</kbd></span>
              <span v-if="audioLabel(map)" class="map-item__audio" :title="audioTitle(map)">
                <AppIcon name="music" :size="13" /> {{ audioLabel(map) }}
              </span>
            </span>
          </span>
        </router-link>

        <div class="map-item__tools">
          <button class="icon-btn" title="Выше" :disabled="index === 0" @click="maps.moveMap(map.id, -1)">
            <AppIcon name="up" :size="16" />
          </button>
          <button
            class="icon-btn"
            title="Ниже"
            :disabled="index === maps.maps.length - 1"
            @click="maps.moveMap(map.id, 1)"
          >
            <AppIcon name="down" :size="16" />
          </button>
          <button class="icon-btn" title="Настройки карты" @click="ui.openEditor(map.id)">
            <AppIcon name="settings" :size="18" />
          </button>
        </div>
      </li>
    </TransitionGroup>

    <button class="btn add-btn" @click="ui.openEditor('new')">
      <AppIcon name="plus" /> Новая карта
    </button>

    <template #footer>
      <div class="hotkeys">
        <span><kbd>M</kbd> карты</span>
        <span><kbd>A</kbd> музыка</span>
        <span><kbd>E</kbd> настройки карты</span>
        <span><kbd>N</kbd> новая карта</span>
        <span><kbd>1</kbd>–<kbd>9</kbd> переключить</span>
        <span><kbd>Space</kbd> пауза звука</span>
        <span><kbd>F</kbd> полный экран</span>
        <span><kbd>0</kbd> сброс зума</span>
      </div>
    </template>
  </SideDrawer>
</template>

<script setup>
import { computed } from 'vue'
import { useRoute } from 'vue-router'
import { useMapsStore } from '@/stores/maps'
import { useUiStore } from '@/stores/ui'
import { useAudioStore } from '@/stores/audio'
import SideDrawer from './SideDrawer.vue'
import AppIcon from './AppIcon.vue'

const maps = useMapsStore()
const ui = useUiStore()
const audio = useAudioStore()
const route = useRoute()

const open = computed(() => ui.panel === 'maps')
const currentId = computed(() => route.params.id)

function onLeave() {
  if (ui.panelByHover) ui.closePanel()
}

function onPick() {
  // на сенсорном экране после выбора меню лучше убрать
  if (!ui.panelByHover && window.matchMedia('(pointer: coarse)').matches) ui.closePanel()
}

function thumbStyle(map) {
  return map.image ? { backgroundImage: `url("${map.image.url}")` } : null
}

function audioLabel(map) {
  if (map.audio.mode === 'stop') return 'тишина'
  if (map.audio.mode !== 'tracks' || !map.audio.tracks.length) return ''
  const first = audio.track(map.audio.tracks[0])
  const name = first ? first.name : '?'
  return map.audio.tracks.length > 1 ? `${name} +${map.audio.tracks.length - 1}` : name
}

function audioTitle(map) {
  return map.audio.tracks.map((id) => audio.track(id)?.name || id).join(', ')
}
</script>

