<template>
  <SideDrawer side="right" :open="open" @close="ui.closePanel()" @leave="onLeave">
    <template #title>
      <h2>Музыка</h2>
    </template>

    <!-- общая громкость -->
    <section class="master">
      <button class="icon-btn" :title="audio.muted ? 'Включить звук' : 'Выключить звук'" @click="audio.toggleMute()">
        <AppIcon :name="audio.muted || audio.master === 0 ? 'mute' : 'volume'" />
      </button>
      <input
        class="range"
        type="range"
        min="0"
        max="1"
        step="0.01"
        :value="audio.master"
        :style="{ '--pct': audio.muted ? '0%' : audio.master * 100 + '%' }"
        title="Общая громкость"
        @input="audio.setMaster(+$event.target.value)"
      />
      <button class="icon-btn" title="Пауза / продолжить (Space)" @click="audio.togglePauseAll()">
        <AppIcon :name="audio.playingIds.length ? 'pause' : 'play'" :size="16" />
      </button>
    </section>

    <label class="switch">
      <input type="checkbox" :checked="audio.autoMapAudio" @change="audio.setAutoMapAudio($event.target.checked)" />
      <span class="switch__track"><span class="switch__thumb" /></span>
      <span>Менять музыку вместе с картой</span>
    </label>

    <!-- сейчас играет -->
    <section v-if="audio.playingIds.length" class="now">
      <h3 class="section-title">Сейчас играет</h3>
      <div v-for="id in audio.playingIds" :key="id" class="now__row">
        <span class="eq"><i /><i /><i /></span>
        <span class="now__name" :title="id">{{ audio.track(id)?.name }}</span>
        <button class="icon-btn" title="Остановить" @click="audio.stop(id)">
          <AppIcon name="stop" :size="14" />
        </button>
      </div>
      <button v-if="currentMap" class="btn btn--ghost bind-btn" @click="bindToMap">
        <AppIcon name="link" :size="16" />
        {{ boundNow ? 'Привязано к карте' : 'Привязать к карте' }} «{{ currentMap.name }}»
      </button>
    </section>

    <!-- поиск -->
    <label v-if="audio.library.tracks.length > 6" class="search">
      <AppIcon name="search" :size="16" />
      <input v-model="query" class="input" type="search" placeholder="Поиск трека…" @keydown.stop />
    </label>

    <!-- библиотека -->
    <section v-for="cat in filtered" :key="cat.name" class="cat" :class="{ 'is-collapsed': collapsed[cat.name] && !query }">
      <button class="cat__head" @click="collapsed[cat.name] = !collapsed[cat.name]">
        <AppIcon name="chevron" :size="16" class="cat__chevron" />
        <span class="cat__name">{{ cat.name }}</span>
        <span class="cat__count">{{ cat.tracks.length }}</span>
      </button>

      <ul v-show="!collapsed[cat.name] || query" class="tracks">
        <li
          v-for="track in cat.tracks"
          :key="track.id"
          class="track"
          :class="{ 'is-playing': audio.isPlaying(track.id), 'has-error': audio.errors[track.id] }"
        >
          <div class="track__row">
            <button
              class="icon-btn track__play"
              :title="audio.isPlaying(track.id) ? 'Остановить' : 'Включить (остальное затихнет)'"
              @click="audio.toggle(track.id)"
            >
              <AppIcon :name="audio.isPlaying(track.id) ? 'stop' : 'play'" :size="14" />
            </button>
            <span class="track__name" :title="audio.errors[track.id] || track.file">{{ track.name }}</span>
            <button
              class="icon-btn"
              :class="{ 'is-on': audio.isPlaying(track.id) && audio.playingIds.length > 1 }"
              title="Наложить поверх текущей музыки"
              @click="audio.toggleLayer(track.id)"
            >
              <AppIcon name="layers" :size="16" />
            </button>
          </div>
          <input
            v-if="audio.isPlaying(track.id)"
            class="range track__volume"
            type="range"
            min="0"
            max="1"
            step="0.01"
            :value="audio.volumeOf(track.id)"
            :style="{ '--pct': audio.volumeOf(track.id) * 100 + '%' }"
            title="Громкость трека"
            @input="audio.setTrackVolume(track.id, +$event.target.value)"
          />
        </li>
      </ul>
    </section>

    <div v-if="!audio.library.tracks.length" class="empty">
      <p>Аудиофайлов пока нет.</p>
      <p>
        Положите их в <code>src/assets/audio/&lt;Категория&gt;/</code> — каждая папка станет разделом.
        Поддерживаются mp3, ogg, opus, wav, flac, m4a, aac, webm.
      </p>
    </div>
    <p v-else-if="query && !filtered.length" class="empty">Ничего не найдено</p>

    <template #footer>
      <div class="foot-hint">
        <span><AppIcon name="play" :size="12" /> — сменить музыку</span>
        <span><AppIcon name="layers" :size="13" /> — наложить слой</span>
      </div>
    </template>
  </SideDrawer>
</template>

<script setup>
import { computed, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { useAudioStore } from '@/stores/audio'
import { useMapsStore } from '@/stores/maps'
import { useUiStore } from '@/stores/ui'
import SideDrawer from './SideDrawer.vue'
import AppIcon from './AppIcon.vue'

const audio = useAudioStore()
const maps = useMapsStore()
const ui = useUiStore()
const route = useRoute()

const open = computed(() => ui.panel === 'audio')
const query = ref('')
const collapsed = reactive({})

const currentMap = computed(() => maps.byId(route.params.id))

const filtered = computed(() => {
  const q = query.value.trim().toLowerCase()
  if (!q) return audio.library.categories
  return audio.library.categories
    .map((cat) => ({
      ...cat,
      tracks: cat.tracks.filter(
        (t) => t.name.toLowerCase().includes(q) || cat.name.toLowerCase().includes(q)
      )
    }))
    .filter((cat) => cat.tracks.length)
})

const boundNow = computed(() => {
  const map = currentMap.value
  if (!map || map.audio.mode !== 'tracks') return false
  const a = [...map.audio.tracks].sort().join('|')
  const b = [...audio.playingIds].sort().join('|')
  return a === b
})

function bindToMap() {
  if (!currentMap.value) return
  maps.updateMap(currentMap.value.id, {
    audio: { mode: 'tracks', tracks: [...audio.playingIds] }
  })
}

function onLeave() {
  if (ui.panelByHover) ui.closePanel()
}
</script>

