import { defineStore } from 'pinia'

export const useUiStore = defineStore('ui', {
  state: () => ({
    // какая панель открыта: null | 'maps' | 'audio'
    panel: null,
    // открыта ли панель наведением (тогда закрывается, когда мышь уходит)
    panelByHover: false,
    // редактор карты: null — закрыт, 'new' — новая, иначе id карты
    editor: null,
    // пользователь недавно двигал мышь / касался экрана
    awake: true,
    fullscreen: false
  }),

  getters: {
    anyOverlay: (s) => s.panel !== null || s.editor !== null
  },

  actions: {
    openPanel(name, { hover = false } = {}) {
      if (this.editor) return
      this.panel = name
      this.panelByHover = hover
    },
    togglePanel(name) {
      if (this.panel === name && !this.panelByHover) this.closePanel()
      else this.openPanel(name)
    },
    closePanel() {
      this.panel = null
      this.panelByHover = false
    },
    openEditor(target) {
      this.closePanel()
      this.editor = target
    },
    closeEditor() {
      this.editor = null
    }
  }
})
