// Принимаем всё, что браузер может считать картинкой. Что именно отрисуется,
// зависит от браузера: png/jpg/webp/gif/avif/bmp/svg/ico — везде,
// tiff/heic — только в Safari (в остальных покажем ошибку).
export const IMAGE_EXTENSIONS = [
  'png', 'jpg', 'jpeg', 'jfif', 'pjpeg', 'pjp', 'gif', 'webp', 'avif', 'apng',
  'bmp', 'svg', 'ico', 'cur', 'tif', 'tiff', 'heic', 'heif'
]

export const IMAGE_ACCEPT = ['image/*', ...IMAGE_EXTENSIONS.map((e) => '.' + e)].join(',')

export function isImageFile(file) {
  if (!file) return false
  if (file.type && file.type.startsWith('image/')) return true
  const ext = (file.name.split('.').pop() || '').toLowerCase()
  return IMAGE_EXTENSIONS.includes(ext)
}

/** Первая картинка из DataTransfer (drag&drop или буфер обмена) */
export function imageFromTransfer(dt) {
  if (!dt) return null
  const files = [...(dt.files || [])]
  const fromFiles = files.find(isImageFile)
  if (fromFiles) return fromFiles
  for (const item of dt.items || []) {
    if (item.kind === 'file') {
      const f = item.getAsFile()
      if (isImageFile(f)) return f
    }
  }
  return null
}

export function transferHasFiles(dt) {
  return !!dt && [...(dt.types || [])].includes('Files')
}
