<template>
  <Transition name="modal">
    <div v-if="target" class="backdrop" @pointerdown.self="cancel">
      <form class="modal panel-surface" @submit.prevent="save">
        <header class="modal__head">
          <h2>{{ isNew ? 'Новая карта' : 'Настройки карты' }}</h2>
          <button type="button" class="icon-btn" title="Закрыть (Esc)" @click="cancel">
            <AppIcon name="close" />
          </button>
        </header>

        <div class="modal__body scroll">
          <!-- изображение -->
          <div
            class="drop"
            :class="{ 'is-over': dragOver, 'has-image': draft.image }"
            @click="pickFile"
            @dragover.prevent="dragOver = true"
            @dragleave="dragOver = false"
            @drop.prevent="onDrop"
          >
            <img
              v-if="draft.image"
              class="drop__preview"
              :src="draft.image.url"
              :style="{ objectFit: draft.fit, transform: `rotate(${draft.rotation}deg)` }"
              alt=""
            />
            <div class="drop__hint" :class="{ 'is-overlay': draft.image }">
              <AppIcon name="image" :size="34" />
              <span v-if="!draft.image">
                Нажмите, перетащите файл или вставьте <kbd>Ctrl</kbd>+<kbd>V</kbd>
              </span>
              <span v-else>Заменить изображение</span>
              <small>PNG, JPG, WEBP, GIF, AVIF, BMP, SVG и другие</small>
            </div>
            <input ref="fileInput" type="file" :accept="IMAGE_ACCEPT" hidden @change="onFileInput" />
          </div>
          <div v-if="draft.image || canResetImage" class="image-meta">
            <span class="image-meta__name" :title="draft.image?.name">{{ draft.image?.name }}</span>
            <button v-if="canResetImage" type="button" class="btn btn--ghost" @click="resetImage">
              Вернуть исходную
            </button>
            <button v-if="draft.image" type="button" class="btn btn--ghost" @click="clearImage">Убрать</button>
          </div>
          <p v-if="fileError" class="error">{{ fileError }}</p>

          <!-- название и иконка -->
          <div class="row">
            <label class="field field--grow">
              <span>Название</span>
              <input ref="nameInput" v-model="draft.name" class="input" maxlength="40" placeholder="Например, Пещера гоблинов" />
            </label>
            <label class="field field--icon">
              <span>Иконка</span>
              <input v-model="draft.icon" class="input input--icon" maxlength="4" />
            </label>
          </div>
          <div class="emoji">
            <button
              v-for="e in EMOJI"
              :key="e"
              type="button"
              class="emoji__btn"
              :class="{ 'is-on': draft.icon === e }"
              @click="draft.icon = e"
            >
              {{ e }}
            </button>
          </div>

          <!-- отображение -->
          <div class="row">
            <div class="field">
              <span>Размещение</span>
              <div class="seg">
                <button type="button" :class="{ 'is-on': draft.fit === 'contain' }" @click="draft.fit = 'contain'">
                  Целиком
                </button>
                <button type="button" :class="{ 'is-on': draft.fit === 'cover' }" @click="draft.fit = 'cover'">
                  На весь экран
                </button>
              </div>
            </div>
            <div class="field">
              <span>Поворот</span>
              <div class="seg">
                <button
                  v-for="deg in [0, 90, 180, 270]"
                  :key="deg"
                  type="button"
                  :class="{ 'is-on': draft.rotation === deg }"
                  @click="draft.rotation = deg"
                >
                  {{ deg }}°
                </button>
              </div>
            </div>
          </div>

          <!-- звук -->
          <div class="field">
            <span>Звук при открытии карты</span>
            <div class="seg seg--wide">
              <button type="button" :class="{ 'is-on': draft.audio.mode === 'keep' }" @click="draft.audio.mode = 'keep'">
                Не менять
              </button>
              <button type="button" :class="{ 'is-on': draft.audio.mode === 'tracks' }" @click="draft.audio.mode = 'tracks'">
                Включить треки
              </button>
              <button type="button" :class="{ 'is-on': draft.audio.mode === 'stop' }" @click="draft.audio.mode = 'stop'">
                Тишина
              </button>
            </div>
          </div>

          <div v-if="draft.audio.mode === 'tracks'" class="picker">
            <p v-if="!audio.library.tracks.length" class="muted">
              В <code>src/assets/audio</code> пока нет файлов.
            </p>
            <template v-for="cat in audio.library.categories" :key="cat.name">
              <div class="picker__cat">{{ cat.name }}</div>
              <label v-for="track in cat.tracks" :key="track.id" class="picker__track">
                <input v-model="draft.audio.tracks" type="checkbox" :value="track.id" />
                <span class="check"><AppIcon name="check" :size="12" /></span>
                <span class="picker__name">{{ track.name }}</span>
                <button
                  type="button"
                  class="icon-btn"
                  :title="audio.isPlaying(track.id) ? 'Остановить' : 'Прослушать'"
                  @click.prevent="audio.toggle(track.id)"
                >
                  <AppIcon :name="audio.isPlaying(track.id) ? 'stop' : 'play'" :size="12" />
                </button>
              </label>
            </template>
            <p v-if="draft.audio.tracks.length > 1" class="muted small">
              Выбрано {{ draft.audio.tracks.length }} — будут звучать одновременно, слоями.
            </p>
          </div>
        </div>

        <footer class="modal__foot">
          <button v-if="!isNew && !original?.preset" type="button" class="btn btn--danger" @click="remove">
            <AppIcon name="trash" :size="16" /> Удалить
          </button>
          <span class="spacer" />
          <button type="button" class="btn btn--ghost" @click="cancel">Отмена</button>
          <button type="submit" class="btn btn--primary">
            <AppIcon name="check" :size="16" /> {{ isNew ? 'Создать' : 'Сохранить' }}
          </button>
        </footer>
      </form>
    </div>
  </Transition>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { useMapsStore, imageFromFile, releaseImage, defaultImageFor } from '@/stores/maps'
import { useAudioStore } from '@/stores/audio'
import { useUiStore } from '@/stores/ui'
import { IMAGE_ACCEPT, isImageFile, imageFromTransfer } from '@/composables/imageFiles'
import AppIcon from './AppIcon.vue'

const EMOJI = ['🍺', '🏰', '🌲', '💀', '🕯️', '⚔️', '🐉', '⛰️', '🌊', '🏜️', '❄️', '🔥', '⛪', '🏚️', '🌙', '🧙', '🌋', '⛵', '🕸️', '👑', '🗺️']

const maps = useMapsStore()
const audio = useAudioStore()
const ui = useUiStore()
const router = useRouter()
const route = useRoute()

const target = computed(() => ui.editor)
const isNew = computed(() => target.value === 'new')
const original = computed(() => (isNew.value ? null : maps.byId(target.value)))

const draft = reactive(emptyDraft())
const fileInput = ref(null)
const nameInput = ref(null)
const dragOver = ref(false)
const fileError = ref('')

function emptyDraft() {
  return { name: '', icon: '🗺️', image: null, fit: 'contain', rotation: 0, audio: { mode: 'keep', tracks: [] } }
}

// при открытии редактора копируем карту в черновик
watch(
  target,
  (t) => {
    if (!t) return
    const src = original.value
    Object.assign(
      draft,
      src
        ? {
            name: src.name,
            icon: src.icon,
            image: src.image,
            fit: src.fit,
            rotation: src.rotation,
            audio: { mode: src.audio.mode, tracks: [...src.audio.tracks] }
          }
        : emptyDraft()
    )
    fileError.value = ''
    nextTick(() => isNew.value && nameInput.value && nameInput.value.focus())
  },
  { immediate: true }
)

const presetId = computed(() => (original.value && original.value.preset ? original.value.id : null))
const canResetImage = computed(
  () => presetId.value && defaultImageFor(presetId.value) && (!draft.image || draft.image.temporary)
)

/** временную картинку, выбранную в черновике, но не сохранённую — освобождаем */
function dropDraftImage() {
  const orig = original.value && original.value.image
  if (draft.image && draft.image.temporary && draft.image !== orig) releaseImage(draft.image)
}

function setDraftFile(file) {
  if (!isImageFile(file)) {
    fileError.value = 'Это не похоже на изображение'
    return
  }
  fileError.value = ''
  dropDraftImage()
  draft.image = imageFromFile(file)
  if (!draft.name.trim()) draft.name = file.name.replace(/\.[^.]+$/, '').replace(/[_-]+/g, ' ')
}

function pickFile() {
  fileInput.value && fileInput.value.click()
}

function onFileInput(e) {
  const file = e.target.files && e.target.files[0]
  if (file) setDraftFile(file)
  e.target.value = ''
}

function onDrop(e) {
  dragOver.value = false
  const file = imageFromTransfer(e.dataTransfer)
  if (file) setDraftFile(file)
  else fileError.value = 'Перетащите файл изображения'
}

function onPaste(e) {
  if (!target.value) return
  const file = imageFromTransfer(e.clipboardData)
  if (file) {
    e.preventDefault()
    setDraftFile(file)
  }
}

function resetImage() {
  dropDraftImage()
  draft.image = defaultImageFor(presetId.value)
}

function clearImage() {
  dropDraftImage()
  draft.image = null
}

function close() {
  ui.closeEditor()
}

function cancel() {
  dropDraftImage()
  close()
}

function save() {
  const audioSettings = {
    mode: draft.audio.mode === 'tracks' && !draft.audio.tracks.length ? 'keep' : draft.audio.mode,
    tracks: draft.audio.mode === 'tracks' ? [...draft.audio.tracks] : []
  }
  const data = {
    name: draft.name.trim() || 'Без названия',
    icon: draft.icon.trim() || '🗺️',
    fit: draft.fit,
    rotation: draft.rotation,
    audio: audioSettings
  }

  if (isNew.value) {
    const id = maps.addMap({ ...data, image: draft.image })
    close()
    router.push(`/map/${id}`)
    return
  }

  const map = original.value
  const audioChanged = JSON.stringify(map.audio) !== JSON.stringify(audioSettings)
  maps.updateMap(map.id, { ...data, image: draft.image })
  close()
  if (audioChanged && route.params.id === map.id) audio.applyMapAudio(map)
}

function remove() {
  const map = original.value
  if (!map || !window.confirm(`Удалить карту «${map.name}»?`)) return
  dropDraftImage()
  const wasCurrent = route.params.id === map.id
  maps.removeMap(map.id)
  close()
  if (wasCurrent && maps.first) router.replace(`/map/${maps.first.id}`)
}

function onKey(e) {
  if (!target.value) return
  if (e.key === 'Escape') {
    e.preventDefault()
    cancel()
  }
}

onMounted(() => {
  window.addEventListener('paste', onPaste)
  window.addEventListener('keydown', onKey)
})
onBeforeUnmount(() => {
  window.removeEventListener('paste', onPaste)
  window.removeEventListener('keydown', onKey)
})
</script>

